		{
			type = "subzone",
			name = "Ambermill",
			areas = { 233 },
		},
	},
	sections = {
		{
			title = "Summary",
			text = [=[The wizards of {link:ambermill}Ambermill{/link} are magi of {link:dalaran}Dalaran{/link} and the servants who guard them: apprentices, conjurers, mages, watchers, warders and protectors, even a brewmaster and a miner. They answer to the {link:kirin-tor}Kirin Tor{/link}, and they have made a sleepy village of {link:silverpine-forest}Silverpine{/link} into a fortress of their own.]=],
		},
		{
			title = "Their Work",
			text = [=[{link:ambermill}Ambermill{/link} sits upon a ley energy node that has long lain dormant. The {link:kirin-tor}Kirin Tor{/link} chose it for that reason, and their archmage {link:archmage-ataeric}Ataeric{/link} has been weaving its energies awake for some great purpose. The runed pendants they carry are old tools of the Kirin Tor, used to channel such power. The wizards also keep a camp north of {link:pyrewood-village}Pyrewood{/link}, where their crates from {link:hillsbrad-foothills}Hillsbrad{/link} arrive.]=],
		},
		{
			title = "Between the Living and the Dead",
			text = [=[To the {link:forsaken}Forsaken{/link}, {link:ambermill}Ambermill{/link} is the heart of human resistance in the forest. The wizards have stood guard on the roads ever since {link:dalaran}Dalaran{/link}'s great barrier fell, and they let no one pass freely. Whatever they fear, they do not say.]=],
		},
	},
})

