Add({
	kind = "figure",
	id = "genn-greymane",
	title = "Genn Greymane",
	aliases = { "Greymane", "King Greymane", "King Genn Greymane" },
	subtitle = "King of Gilneas",
	tier = "A",
	region = "silverpine-forest",
	allegiance = "Kingdom of Gilneas",
	found = "Behind the Greymane Wall, in Gilneas",
	unlock = {
		{ type = "read" },
	},
	hint = "Learn of the king whose wall seals the south of Silverpine.",
	sections = {
		{
			title = "Summary",
			text = [=[Genn Greymane is the king of {link:gilneas}Gilneas{/link}. He is a proud and stubborn ruler, a warrior who trusts his own people and few others. It was he who withdrew Gilneas from the {link:alliance}Alliance{/link} after the {link:second-war}Second War{/link}, and he who raised the great wall across the south of {link:silverpine-forest}Silverpine{/link}. Behind that wall his kingdom has kept its own counsel through all the ruin of the north.]=],
		},
		{
			title = "Significance",
			text = [=[Greymane is the lord who chose to stand alone. His wall spared {link:gilneas}Gilneas{/link} the costs of other nations' wars. It also left the north to face the {link:scourge}Scourge{/link} without the Gilnean army. Whether the wall saved his kingdom or only hid it, no one outside can tell.]=],
		},
		{
			title = "Deeds",
			text = [=[• When {link:stormwind-city}Stormwind{/link} fell, he came with the other human rulers to the council in {link:lordaeron}Lordaeron{/link} called by King {link:terenas-menethil}Terenas{/link}. He doubted the danger, and boasted that the army of {link:gilneas}Gilneas{/link} could meet any threat.
• He joined the {link:alliance}Alliance of Lordaeron{/link} with reluctance, and gave it far less than his realm could have given.
• After the war he quarrelled with his fellow kings over the cost of the orcish internment camps and of {link:nethergarde-keep}Nethergarde Keep{/link}. When he complained of the keep's expense, the young King {link:varian-wrynn}Varian Wrynn{/link} answered that no price could be set on their safety.
• He sought a hand in the fate of leaderless {link:alterac-mountains}Alterac{/link}, and backed a claimant to its throne.
• He withdrew Gilneas from the Alliance, built the {link:the-greymane-wall}Greymane Wall{/link} and closed its gates.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No word has come out of {link:gilneas}Gilneas{/link} since its gates were closed. What King Greymane knows of the worgen at his door, and what passes in his kingdom, no chronicle of these days can say.]=],
		},
	},
	chapters = {
		{
			key = "the-wall-of-his-name",
			title = "The Wall of His Name",
			hint = "Stand before the wall that bears the king's name.",
			unlock = {
				{
					type = "subzone",
					name = "The Greymane Wall",
					areas = { 230 },
				},
			},
			text = [=[Greymane believed that {link:gilneas}Gilneas{/link} owed nothing to the wars of other realms. When the {link:alliance}Alliance{/link} asked his people to pay for the prison camps of the orcs, he refused, and he took his kingdom out of the Alliance altogether. Then he walled it off. {link:the-greymane-wall}The Greymane Wall{/link} rose across the northern border of Gilneas. When the plague came to {link:lordaeron}Lordaeron{/link}, its gates stayed shut. No Gilnean army marched north to help the dying kingdom.]=],
		},
		{
			key = "the-closed-gates",
			title = "The Closed Gates",
			hint = [=[Help the Forsaken stop the curse from spreading among the refugees at the wall.]=],
			unlock = {
				{ type = "quest", id = 98299 },
			},
			text = [=[Now refugees from the north huddle at the foot of the wall, sick and hungry. They hoped to find shelter in {link:gilneas}Gilneas{/link}. The Gilneans have made it plain that they will let no one through. The {link:forsaken}Forsaken{/link}, who fear the curse of the worgen, find that a comfort. They say that at least the curse cannot pass the gates.]=],
		},
	},
	mentions = {
		{
			text = "Stop the Spread",
			unlock = {
				{ type = "quest", id = 98299 },
			},
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "called the council he joined" },
		{ id = "the-greymane-wall", name = "The Greymane Wall", note = "his work" },
	},
})
